        stringArrayArray2[5] = new String[]{"08", "Th\u01b0a \u0111\u1ea1i v\u01b0\u01a1ng, 12 s\u1ee9 qu\u00e2n \u0111\u00e1ng g\u1eddm nh\u1ea5t l\u00e0 Ph\u1ea1m B\u1ea1ch H\u1ed5. \u00d4ng ta v\u1ed1n l\u00e0m t\u01b0\u1edbng d\u01b0\u1edbi th\u1eddi Ng\u00f4 V\u01b0\u01a1ng l\u1ea1i l\u00e0 ng\u01b0\u1eddi c\u00f3 uy \u0111\u1ee9c. Qu\u00e2n s\u0129 \u0111\u01b0\u1ee3c hu\u1ea5n luy\u1ec7n r\u1ea5t b\u00e0i b\u1ea3n, qu\u00e2n th\u1ee7y b\u1ed9 uy d\u0169ng. \u0110\u00e1nh Ph\u1ea1m B\u1ea1ch H\u1ed5 n\u1ebfu th\u1eafng th\u00ec uy phong r\u1ea5t l\u1edbn, n\u1ebfu thua qu\u00e2n ta s\u1ebd m\u1ea5t nhu\u1ec7 kh\u00ed m\u00e0 c\u00e1c s\u1ee9 qu\u00e2n kh\u00e1c c\u0169ng xem th\u01b0\u1eddng."};
        stringArrayArray2[6] = new String[]{"07", "T\u1eadp trung to\u00e0n qu\u00e2n, \u0111\u00e1nh m\u1ed9t tr\u1eadn quy\u1ebft t\u1eed. Th\u1eafng \u0111\u01b0\u1ee3c Ph\u1ea1m B\u1ea1ch H\u1ed5 xem nh\u01b0 ta c\u00f3 n\u1eeda giang s\u01a1n. S\u1ee3 g\u00ec !"};
        stringArrayArray2[7] = new String[]{"08", "Kh\u00f4ng \u0111\u01b0\u1ee3c! K\u1ebf \u0111\u00f3 l\u00e0 \u201c\u0110\u01b0\u1ee3c \u0103n c\u1ea3 ng\u00e3 v\u1ec1 kh\u00f4ng\u201d. T\u1ed1t nh\u1ea5t l\u00e0 ta c\u1ee9 theo binh ph\u00e1p c\u01a1 b\u1ea3n, \u0111\u00e1nh k\u1ebb y\u1ebfu h\u00f2a k\u1ebb m\u1ea1nh, x\u01b0a nay v\u1eabn th\u1ebf. Ta n\u00ean h\u00f2a v\u1edbi Ph\u1ea1m B\u1ea1ch H\u1ed5."};
        stringArrayArray2[8] = new String[]{"06", "V\u1eady ai s\u1ebd l\u00e0 ng\u01b0\u1eddi \u0111i sang thuy\u1ebft kh\u00e1ch \u0111\u00e2y?"};
        stringArrayArray2[9] = new String[]{"08", "Nhi\u1ec7m v\u1ee5 thuy\u1ebft kh\u00e1ch, xin \u0111\u1ec3 L\u01b0u C\u01a1!"};
        stringArrayArray2[10] = new String[]{"06", "Chuy\u1ebfn \u0111i l\u00e0nh \u00edt d\u1eef nhi\u1ec1u, t\u01b0\u1edbng qu\u00e2n {p} h\u00e3y \u0111i c\u00f9ng qu\u00e2n s\u01b0. Hai v\u1ecb h\u00e3y c\u1ea9n tr\u1ecdng."};
