        stringArrayArray[5] = stringArrayArray2;
        stringArrayArray[6] = new String[][]{{"08", "L\u01b0u C\u01a1 \u1edf Hoa L\u01b0, xin b\u00e1i ki\u1ebfn Ph\u1ea1m s\u1ee9 qu\u00e2n!!"}, {"18", "L\u01b0u ti\u00ean sinh, m\u1eddi an t\u1ecda! "}, {"18", "Ch\u1eb3ng hay L\u01b0u qu\u00e2n s\u01b0 \u0111\u1ebfn x\u1ee9 \u0110\u1eb1ng Ch\u00e2u c\u00f3 vi\u1ec7c g\u00ec?"}, {"08", "Ch\u1ee7 t\u01b0\u1edbng t\u00f4i c\u00f3 th\u01b0 n\u00e0y g\u1eedi Ph\u1ea1m s\u1ee9 qu\u00e2n, xin s\u1ee9 qu\u00e2n xem qua."}, {"18", "H\u00e3y \u0111\u01b0a th\u01b0 cho ta..........."}, {"18", "Th\u01b0 ta \u0111\u00e3 \u0111\u1ecdc, chuy\u1ec7n an h\u00f2a nghe c\u0169ng thu\u1eadn l\u00f2ng. Nh\u01b0ng c\u00f2n ph\u1ea3i xem \u00fd tr\u1eddi ra sao?"}, {"18", "Nghe n\u00f3i ti\u00ean sinh tinh th\u00f4ng K\u1ef3 m\u00f4n \u0111\u1ed9n gi\u00e1p. \u00d4ng h\u00e3y xem \u00fd tr\u1eddi gi\u00fap t\u00f4i."}, {"08", "M\u1eddi s\u1ee9 qu\u00e2n gieo qu\u1ebb!"}, {"08", "Qu\u1ebb c\u1ee7a t\u01b0\u1edbng qu\u00e2n l\u00e0 qu\u1ebb Th\u1ee7y \u0110\u1ecba T\u1ef7. L\u1eddi qu\u1ebb n\u00f3i r\u1eb1ng \u201cL\u1ee5c nh\u1ecb: t\u1ef7 chi t\u1eed n\u1ed9i, trinh c\u00e1t\u201d. Xin d\u1ecbch ngh\u0129a nh\u01b0 sau: \u201c Hai b\u00ean th\u00e2n nhau v\u00ec \u0111\u1ea1o \u0111\u1ed3ng ch\u00ed h\u1ee3p, ch\u1ee9 kh\u00f4ng ph\u1ea3i v\u00ec k\u1ebft th\u00e2n v\u1edbi b\u1ec1 tr\u00ean \u0111\u1ec3 c\u1ea7u ph\u00fa qu\u00ed, nh\u01b0 v\u1eady l\u00e0 ch\u00ednh \u0111\u00e1ng, kh\u00f4ng th\u1ea5t th\u00e2n, n\u00ean t\u1ed1t. \u201d"}, {"18", "\u00dd tr\u1eddi \u0111\u00e3 v\u1eady, B\u1ea1ch H\u1ed5 kh\u00f4ng d\u00e1m tr\u00e1i thi\u00ean \u00fd. "}, {"18", "Qu\u00e2n s\u01b0 h\u00e3y mang h\u00f2a \u01b0\u1edbc n\u00e0y v\u1ec1 Hoa L\u01b0. T\u1eeb nay, ch\u00fang ta hi\u1ebfu h\u00f2a, kh\u00f4ng x\u00e2m l\u1ea5n, kh\u00f4ng g\u00e2y phi\u1ec1n h\u00e0 cho nhau, ai gi\u00e0u n\u1ea5y h\u01b0\u1edfng, ai m\u1ea1nh t\u1ef1 c\u01b0\u1eddng, t\u00ecnh h\u1eefu h\u1ea3o l\u00e1ng gi\u1ec1ng, tr\u01b0\u1edbc sau nh\u01b0 m\u1ed9t. N\u1ebfu c\u00f3 k\u1ebb \u0111\u00e1nh Hoa L\u01b0, Ph\u1ea1m B\u1ea1ch H\u1ed5 s\u1eb5n l\u00f2ng gi\u00fap \u0111\u1ee1."}, {"08", "L\u01b0u C\u01a1 thay m\u1eb7t V\u1ea1n Th\u1eafng V\u01b0\u01a1ng v\u00f4 c\u00f9ng c\u1ea3m k\u00edch Ph\u1ea1m s\u1ee9 qu\u00e2n!"}};
        stringArrayArray[7] = new String[][]{{"06", "Ta \u0111\u00e3 h\u00f2a v\u1edbi Ph\u1ea1m B\u1ea1ch H\u1ed5, v\u1eady g\u1ea7n Hoa L\u01b0 nh\u1ea5t ch\u1ec9 c\u00f2n Ng\u00f4 X\u01b0\u01a1ng X\u00ed \u1edf B\u00ecnh Ki\u1ec1u."}, {"07", "Con th\u1ecf non tr\u1ed1n ch\u1ea1y v\u1ec1 mi\u1ec1n r\u1eebng n\u00fai \u00e2m u \u1ea5y, \u0111\u00e1ng k\u1ec3 g\u00ec!  "}, {"08", "Nh\u01b0ng c\u0169ng kh\u00f4ng th\u1ec3 ch\u1ee7 quan, n\u1ebfu l\u1ea5y \u0111\u01b0\u1ee3c B\u00ecnh Ki\u1ec1u th\u00ec s\u1ebd an t\u00e2m h\u01a1n khi ti\u1ebfn qu\u00e2n l\u00ean ph\u00eda b\u1eafc."}, {"06", "X\u01b0\u01a1ng X\u00ed th\u00e2n l\u00e0 ch\u00e1u Ng\u00f4 V\u01b0\u01a1ng, di\u1ec7t h\u1eafn th\u00ec thi\u00ean h\u1ea1 s\u1ebd c\u00f3 nhi\u1ec1u l\u1eddi kh\u00f4ng hay. Ta n\u00ean chi\u00eau h\u00e0ng h\u1eafn, Nguy\u1ec5n B\u1eb7c \u1edf Hoa L\u01b0 ph\u00f2ng th\u1ee7. Nh\u1eefng ng\u01b0\u1eddi c\u00f2n l\u1ea1i theo ta."}, {"00", "Tu\u00e2n l\u1ec7nh \u0110\u1ea1i V\u01b0\u01a1ng."}};
        stringArrayArray[8] = new String[][]{{"00", "Ng\u00f4 X\u01b0\u01a1ng X\u00ed! B\u00ecnh Ki\u1ec1u \u0111\u00e3 b\u1ecb bao v\u00e2y, kh\u00f4n ngoan h\u00e3y mau ra h\u00e0ng."}, {"22", "C\u00f3 th\u1ef1c l\u1ef1c th\u00ec \u0111\u1ebfn \u0111\u00e2y, \u0111\u1eebng nhi\u1ec1u l\u1eddi."}};
        stringArrayArray[9] = new String[][]{{"06", "Tr\u01b0\u1edbc m\u1eb7t ta c\u00f3 \u0110\u1ed7 C\u1ea3nh Th\u1ea1c v\u00e0 Ng\u00f4 Nh\u1eadt Kh\u00e1nh. Qu\u00e2n s\u01b0, ch\u00fang ta n\u00ean \u0111\u00e1nh ai tr\u01b0\u1edbc."}, {"08", "\u0110\u1ed7 C\u1ea3nh Th\u1ea1c l\u00e0 l\u00e3o t\u01b0\u1edbng d\u00e0y d\u1eb7n kinh nghi\u1ec7m, c\u00f3 th\u00e0nh tr\u00ec ch\u1eafc ch\u1eafn v\u00e0 h\u00e0o s\u00e2u bao quanh, n\u1ebfu \u0111\u00e1nh tr\u01b0\u1edbc ch\u1eafn ch\u1eafn l\u1ef1c l\u01b0\u1ee3ng s\u1ebd hao t\u1ed5n r\u1ea5t nhi\u1ec1u. Ng\u00f4 Nh\u1eadt Kh\u00e1nh th\u00ec \u1edf r\u1ea5t xa, ch\u1ec9 c\u00f3 m\u1ed9t \u0111\u01b0\u1eddng duy nh\u1ea5t \u0111\u1ebfn \u0111\u00f3 l\u1ea1i g\u1eadp gh\u1ec1nh nguy hi\u1ec3m. Qu\u00e2n ta \u0111\u1ebfn n\u01a1i th\u00ec c\u0169ng r\u1ea5t m\u1ec7t m\u1ecfi, s\u1ee9c \u0111\u00e2u m\u00e0 \u0111\u00e1nh tr\u1eadn."}, {"07", "G\u1ea7n kh\u00f4ng \u0111\u00e1nh \u0111\u01b0\u1ee3c, Xa c\u0169ng kh\u00f4ng \u0111\u01b0\u1ee3c \u0111\u00e1nh. V\u1eady ta \u1edf \u0111\u00e2y l\u00e0m g\u00ec ?!"}, {"06", "Haha, t\u01b0\u1edbng qu\u00e2n! H\u00e3y \u0111\u1ec3 qu\u00e2n s\u01b0 n\u00f3i ti\u1ebfp xem sao."}, {"08", "T\u01b0\u1edbng qu\u00e2n, h\u00e3y b\u00ecnh t\u0129nh. \u0110\u00e1nh ai tr\u01b0\u1edbc, ta c\u0169ng ph\u1ea3i b\u00e0n t\u00ednh k\u1ef9 c\u00e0ng."}, {"08", "Th\u01b0a \u0110\u1ea1i V\u01b0\u01a1ng, trong 2 s\u1ee9 qu\u00e2n th\u00ec Ng\u00f4 Nh\u1eadt Kh\u00e1nh l\u00e0 y\u1ebfu nh\u1ea5t, tuy th\u00f4ng minh nh\u01b0ng c\u00f2n r\u1ea5t tr\u1ebb, \u00edt tr\u1ea3i nghi\u1ec7m v\u00e0 r\u1ea5t b\u1ed1c \u0111\u1ed3ng. \u0110\u00e1nh Kh\u00e1nh tr\u01b0\u1edbc l\u00e0 th\u00edch h\u1ee3p nh\u1ea5t m\u00e0 kh\u1ea3 n\u0103ng hao t\u1ed5n l\u1ef1c l\u01b0\u1ee3ng \u00edt h\u01a1n so v\u1edbi nh\u1eefng ng\u01b0\u1eddi kh\u00e1c. Nh\u01b0ng ta c\u0169ng ph\u1ea3i \u0111\u1ec1 ph\u00f2ng \u0110\u1ed7 C\u1ea3nh Th\u1ea1c \u0111\u00e1nh t\u1eeb ph\u00eda sau l\u1ea1i. "}, {"08", "T\u00f4i c\u00f3 \u00fd n\u00e0y. \u0110em qu\u00e2n gi\u1ea3 \u0111\u00e1nh C\u1ea3nh Th\u1ea1c, \u0111\u1ebfn \u00d4 Man chia qu\u00e2n l\u00e0m 3 \u0111\u1ea1o. \u0110\u1ea1o th\u1ee9 nh\u1ea5t do t\u01b0\u1edbng Nguy\u1ec5n B\u1eb7c ch\u1ec9 huy \u0111\u00f3ng \u1edf \u00d4 Man, \u0111\u1ea1o th\u1ee9 2 do \u0110\u1ea1i v\u01b0\u01a1ng ch\u1ec9 huy \u0111\u00f3ng tr\u1ef1c di\u1ec7n v\u1edbi \u0111\u1ed3n B\u1ea3o \u0110\u00e0. \u0110\u1ea1o th\u1ee9 3 s\u1ebd do t\u01b0\u1edbng {p} d\u1eabn \u0111\u1ea7u, b\u00ed m\u1eadt \u0111i \u0111\u1ebfn \u0110\u01b0\u1eddng L\u00e2m b\u1ea5t ng\u1edd \u0111\u1ebfn \u0111\u00e1nh Ng\u00f4 Nh\u1eadt Kh\u00e1nh ch\u1eafc ch\u1eafn h\u1eafn s\u1ebd tr\u01a1 tay kh\u00f4ng k\u1ecbp."}, {"06", "T\u1ed1t! M\u1ecdi ng\u01b0\u1eddi h\u00e3y y theo m\u00e0 h\u00e0nh \u0111\u1ed9ng."}, {"00", "Tu\u00e2n l\u1ec7nh \u0110\u1ea1i V\u01b0\u01a1ng"}};
        stringArrayArray[10] = new String[][]{{"27", "B\u1ecdn ng\u01b0\u01a1i l\u00e0 qu\u00e2n c\u1ee7a ai, mu\u1ed1n ch\u1ebft hay sao m\u00e0 \u0111\u00e1m \u0111\u1ebfn \u0111\u00e2y l\u00e0m lo\u1ea1n?"}, {"00", "Ta l\u00e0 {p}, t\u01b0\u1edbng ti\u00ean phong c\u1ee7a V\u1ea1n Th\u1eafng V\u01b0\u01a1ng, h\u00f4m nay ta \u0111\u1ebfn l\u1ea5y \u0111\u1ea7u ng\u01b0\u01a1i!"}, {"27", "L\u00e1o x\u01b0\u1ee3c! Ta s\u1ebd ph\u00e2n th\u00e2y ng\u01b0\u01a1i \u0111\u1ec3 l\u00e0m g\u01b0\u01a1ng cho k\u1ebb kh\u00e1c."}};
        stringArrayArray[11] = new String[][]{{"08", "L\u00e3 \u0110\u01b0\u1eddng \u1edf T\u1ebf Giang \u0111\u00e3 c\u1ea5t binh \u0111\u00e1nh Ph\u1ea1m B\u1ea1ch H\u1ed5. Ta \u0111\u00e3 c\u00f3 h\u00f2a \u01b0\u1edbc v\u1edbi B\u1ea1ch H\u1ed5, n\u00ean kh\u00f4ng th\u1ec3 kh\u00f4ng gi\u00fap, h\u01a1n n\u1eefa n\u1ebfu \u0110\u1eb1ng Ch\u00e2u m\u1ea5t th\u00ec K\u1ef3 B\u1ed1 c\u0169ng s\u1ebd kh\u00f3 m\u00e0 y\u00ean. \u0110\u1ea1i V\u01b0\u01a1ng v\u00e0 t\u01b0\u1edbng Nguy\u1ec5n B\u1eb7c \u0111ang gi\u1eef ch\u00e2n C\u1ea3nh Th\u1ea1c kh\u00f4ng th\u1ec3 \u0111em qu\u00e2n ti\u1ebfp \u1ee9ng. Th\u1eddi gian c\u1ea5p b\u00e1ch, t\u01b0\u1edbng qu\u00e2n h\u00e3y \u0111em qu\u00e2n \u1ee9ng c\u1ee9u tr\u01b0\u1edbc, t\u00f4i s\u1ebd theo sau. Trong 5 ng\u00e0y ch\u00fang ta ph\u1ea3i \u0111\u1ebfn \u0111\u00f3, n\u1ebfu kh\u00f4ng th\u00ec \u0110\u1eb1ng Ch\u00e2u kh\u00f3 m\u00e0 gi\u1eef \u0111\u01b0\u1ee3c."}, {"00", "L\u01b0u qu\u00e2n s\u01b0 y\u00ean t\u00e2m, m\u1ea1t t\u01b0\u1edbng s\u1ebd \u0111i ngay!"}};
        stringArrayArray[12] = new String[][]{{"00", "Ph\u1ea1m s\u1ee9 qu\u00e2n! C\u00f3 t\u00f4i \u0111\u1ebfn tr\u1ee3 gi\u00fap \u0111\u00e2y."}, {"20", "H\u1eeb, qu\u00e2n gi\u1eb7c c\u00f3 vi\u1ec7n binh, kh\u00f4ng xong r\u1ed3i!"}, {"00", "L\u00e3o \u00e1c t\u1eb7c, h\u00e3y xem \u0111\u00e2y!"}};
        stringArrayArray[13] = new String[][]{{"18", "\u0110a t\u1ea1 t\u01b0\u1edbng qu\u00e2n gi\u00fap \u0111\u1ee1."}, {"00", "Ch\u00fang ta l\u00e0 ng\u01b0\u1eddi m\u1ed9t nh\u00e0, Ph\u1ea1m s\u1ee9 qu\u00e2n xin \u0111\u1eebng kh\u00e1ch s\u00e1o."}, {"08", "Sau tr\u1eadn v\u1eeba r\u1ed3i binh l\u1ef1c c\u1ee7a L\u00e3 \u0110\u01b0\u1eddng \u0111\u00e3 suy y\u1ebfu, nhu\u1ec7 kh\u00ed kh\u00f4ng c\u00f2n. H\u01a1n n\u1eefa qu\u00e2n ta l\u1ea1i \u0111\u00f4ng h\u01a1n, h\u00e0o kh\u00ed ng\u1ea5t tr\u1eddi. Nh\u00e2n c\u01a1 h\u1ed9i n\u00e0y, ti\u1ebfn qu\u00e2n \u0111\u00e1nh v\u00e0o T\u1ebf Giang ch\u1eafc ch\u1eafn s\u1ebd h\u1ea1 \u0111\u01b0\u1ee3c."}, {"18", "L\u01b0u qu\u00e2n s\u01b0 n\u00f3i ph\u1ea3i l\u1eafm. M\u1ecdi ng\u01b0\u1eddi ngh\u1ec9 ng\u01a1i l\u1ea5y s\u1ee9c, s\u1edbm mai xu\u1ea5t qu\u00e2n."}, {"08", "L\u01b0u C\u01a1 xin c\u00e1o lui."}, {"00", "{p} xin c\u00e1o lui."}};
        stringArrayArray[15] = new String[][]{{"00", "L\u00e3 \u0110\u01b0\u1eddng, ta \u0111\u1ebfn l\u1ea5y \u0111\u1ea7u ng\u01b0\u01a1i \u0111\u00e2y!"}, {"20", "V\u1edbi s\u1ee9c ng\u01b0\u01a1i \u01b0? \u1ea2o t\u01b0\u1edfng ! S\u00e1ttttt"}};
        stringArrayArray[16] = new String[][]{{"08", "Ph\u1ea1m s\u1ee9 qu\u00e2n, T\u1ebf Giang \u0111\u00e3 di\u1ec7t xong. Ch\u00fang t\u00f4i ph\u1ea3i tr\u1edf v\u1ec1, L\u01b0u C\u01a1 xin b\u00e1i bi\u1ec7t!"}, {"18", "L\u01b0u qu\u00e2n s\u01b0, V\u1ea1n Th\u1eafng V\u01b0\u01a1ng l\u00e0 ng\u01b0\u1eddi nh\u00e2n ngh\u0129a l\u1ea1i c\u00f3 ch\u00ed l\u1edbn b\u00ecnh \u0111\u1ecbnh thi\u00ean h\u1ea1, \u0111\u00fang l\u00e0 ph\u01b0\u1edbc c\u1ee7a mu\u00f4n d\u00e2n. N\u1ebfu B\u1ea1ch H\u1ed5 \u0111\u01b0\u1ee3c gi\u00fap m\u1ed9t tay th\u00ec th\u1eadt l\u00e0 vinh h\u1ea1nh l\u1eafm l\u1eafm!"}, {"08", "L\u01b0u C\u01a1 s\u1ebd chuy\u1ec3n t\u00e2m \u00fd c\u1ee7a Ph\u1ea1m s\u1ee9 qu\u00e2n \u0111\u1ebfn V\u1ea1n Th\u1eafng V\u01b0\u01a1ng. "}, {"18", "\u0110a t\u1ea1 qu\u00e2n s\u01b0!"}, {"08", "Nh\u1ea5t \u0111\u1ecbnh s\u1ebd c\u00f3 ng\u00e0y ch\u00fang ta g\u1eb7p l\u1ea1i. Ph\u1ea1m s\u1ee9 qu\u00e2n, h\u1eb9n ng\u00e0y t\u00e1i ng\u1ed9!"}, {"18", "L\u01b0u qu\u00e2n s\u01b0, h\u00e3y b\u1ea3o tr\u1ecdng!"}};
        stringArrayArray[17] = new String[][]{{"06", "Qu\u00e2n s\u01b0, \u00f4ng \u0111\u1ebfn th\u1eadt \u0111\u00fang l\u00fac, qu\u00e2n \u0111\u1ecbch ph\u00f2ng th\u1ee7 r\u1ea5t ch\u1eb7t, ta kh\u00f3 m\u00e0 \u0111\u00e1nh v\u00e0o \u0111\u01b0\u1ee3c."}, {"08", "\u0110\u1ea1i v\u01b0\u01a1ng y\u00ean t\u00e2m, c\u01a1 h\u1ed9i c\u1ee7a ch\u00fang ta \u0111\u00e3 \u0111\u1ebfn. \u0110\u1ed7 C\u1ea3nh Th\u1ea1c \u0111ang \u1edf \u0111\u1ed3n B\u1ea3o \u0110\u00e0, th\u00e0nh Qu\u00e8n \u1edf \u0110\u1ed7 \u0110\u1ed9ng kh\u00f4ng ng\u01b0\u1eddi ch\u1ec9 huy ch\u1eafc ch\u1eafn s\u1ebd c\u00f3 s\u1edf h\u1edf. \u0110\u00eam mai ch\u1ee7 c\u00f4ng, c\u00f9ng t\u01b0\u1edbng {p} d\u1eabn qu\u00e2n qu\u00e2n v\u00e2y th\u00e0nh, sau \u0111\u00f3 \u0111\u1ed1t l\u1eeda th\u1eadt l\u1edbn. Th\u1ea5y l\u1eeda ch\u1eafc ch\u1eafn C\u1ea3nh Th\u1ea1c s\u1ebd r\u00fat qu\u00e2n t\u1eeb B\u1ea3o \u0110\u00e0 v\u1ec1 \u1ee9ng c\u1ee9u, t\u00ecnh h\u00ecnh \u1edf B\u1ea3o \u0110\u00e0 l\u1eabn th\u00e0nh Qu\u00e8n s\u1ebd x\u1ea3y ra h\u1ed7n lo\u1ea1n. Khi \u0111\u00f3 \u0110\u1ea1i v\u01b0\u01a1ng quay \u0111\u1ea7u t\u1ea5n c\u00f4ng C\u1ea3nh Th\u1ea1c, c\u00f9ng l\u00fac t\u01b0\u1edbng Nguy\u1ec5n B\u1eb7c v\u00e0 L\u00ea Ho\u00e0n t\u1ea5n c\u00f4ng th\u1eb3ng v\u00e0o B\u1ea3o \u0110\u00e0, \u00e9p C\u1ea3nh Th\u1ea1c v\u00e0o gi\u1eefa. B\u1ecb t\u1ea5n c\u00f4ng b\u1ea5t ng\u1edd \u0111\u1ecbch s\u1ebd ho\u1ea3ng lo\u1ea1n, qu\u00e2n ta \u1eaft s\u1ebd th\u00e0nh c\u00f4ng."}, {"06", "\u0110\u01b0\u1ee3c! Ta s\u1ebd l\u00e0m theo c\u00e1ch n\u00e0y. \u0110\u00eam mai s\u1ebd h\u00e0nh \u0111\u1ed9ng, m\u1ecdi ng\u01b0\u1eddi h\u00e3y chu\u1ea9n b\u1ecb."}};
        stringArrayArray[18] = new String[][]{{"24", "Th\u00e0nh Qu\u00e8n b\u1ecb t\u1ea5n c\u00f4ng, ta ph\u1ea3i v\u1ec1 c\u1ee9u ngay, c\u00e1c ng\u01b0\u1eddi h\u00e3y \u1edf l\u1ea1i c\u1ed1 th\u1ee7."}, {"00", "C\u1ea3nh Th\u1ea1c!! Ng\u01b0\u01a1i \u0111\u00e3 h\u1ebft \u0111\u01b0\u1eddng ch\u1ea1y, mu\u1ed1n s\u1ed1ng h\u00e3y mau ch\u1ecbu tr\u00f3i."}, {"24", "Hahaha, th\u1eadt n\u1ef1c c\u01b0\u1eddi ! Ch\u1ec9 m\u1ed9t \u0111\u00e1m tr\u1ebb con m\u00e0 d\u00e1m c\u1ea3n \u0111\u01b0\u1eddng ta \u01b0? C\u00f3 b\u1ea3n l\u0129nh th\u00ec h\u00e3y \u0111\u1ebfn \u0111\u00e2y."}};
        stringArrayArray[19] = new String[][]{{"08", "\u0110\u1ea1i v\u01b0\u01a1ng! \u0110\u1ed7 \u0110\u1ed9ng Giang \u0111\u00e3 l\u1ea5y \u0111\u01b0\u1ee3c, nh\u01b0ng qu\u00e2n l\u1ef1c ta hao t\u1ed5n kh\u00e1 n\u1eb7ng. N\u1ebfu \u0111\u00e1nh lu\u00f4n T\u00e2y Ph\u00f9 Li\u1ec7t th\u00ec r\u1ea5t kh\u00f3, t\u1ed1t nh\u1ea5t n\u00ean \u00e1n binh b\u1ea5t \u0111\u1ed9ng \u0111\u1ec3 c\u0169ng c\u1ed1 l\u1ef1c l\u01b0\u1ee3ng. M\u1eb7t kh\u00e1c \u0110\u1ea1i v\u01b0\u01a1ng n\u00ean \u0111\u00edch th\u00e2n \u0111\u1ebfn \u0110\u1eb1ng Ch\u00e2u ti\u1ebfp nh\u1eadn binh l\u1ef1c c\u1ee7a Ph\u1ea1m B\u1ea1ch H\u1ed5."}, {"06", "\u1eeam, B\u1ea1ch H\u1ed5 \u0111\u00e3 c\u00f3 \u00fd v\u1ec1 \u0111\u1ea7u qu\u00e2n, ta c\u0169ng n\u00ean \u0111\u1ebfn g\u1eb7p tr\u1ef1c ti\u1ebfp \u00f4ng ta. C\u00f3 th\u00eam binh l\u1ef1c c\u1ee7a \u0110\u1eb1ng Ch\u00e2u th\u00ec vi\u1ec7c di\u1ec7t Nguy\u1ec5n Si\u00eau c\u0169ng kh\u00f4ng qu\u00e1 kh\u00f3 kh\u0103n. "}, {"08", "\u0110\u01b0\u1eddng xa nguy hi\u1ec3m, ng\u01b0\u1eddi n\u00ean \u0111\u1ec3 L\u00ea Ho\u00e0n t\u01b0\u1edbng qu\u00e2n \u0111i c\u00f9ng."}, {"06", "Vi\u1ec7c \u1edf \u0111\u00e2y qu\u00e2n s\u01b0 h\u00e3y c\u1ed1 s\u1eafp x\u1ebfp."}, {"08", "\u0110\u1ea1i v\u01b0\u01a1ng h\u00e3y y\u00ean t\u00e2m!"}};
        stringArrayArray[20] = new String[][]{{"07", "Kh\u00f4ng xong! Qu\u00e2n s\u01b0! Qu\u00e2n s\u01b0!! Nguy\u1ec5n Si\u00eau \u0111\u00e3 v\u00e2y th\u00e0nh!"}, {"08", "Nguy\u1ec5n Si\u00eau \u0111\u00e3 \u0111\u00e1nh \u0110\u1ed7 \u0110\u1ed9ng s\u1edbm h\u01a1n ta d\u1ef1 t\u00ednh. Binh l\u1ef1c v\u00e0 l\u01b0\u01a1ng th\u1ea3o hi\u1ec7n t\u1ea1i ch\u1ec9 c\u00f3 th\u1ec3 c\u1ed1 th\u1ee7 ch\u1edd vi\u1ec7n binh t\u1eeb \u0110\u1eb1ng Ch\u00e2u \u0111\u1ebfn. Nguy\u1ec5n B\u1eb7c h\u00e3y tr\u1ea5n th\u1ee7 \u1edf c\u1eeda T\u00e2y, c\u1eeda b\u1eafc m\u1ecdi s\u1ef1 tr\u00f4ng c\u1eady v\u00e0o {p} t\u01b0\u1edbng qu\u00e2n. N\u0103m ng\u00e0y n\u1eefa qu\u00e2n vi\u1ec7n binh s\u1ebd \u0111\u1ebfn, m\u1ecdi ng\u01b0\u1eddi h\u00e3y c\u1ed1 g\u1eafng th\u1ee7 th\u00e0nh."}, {"29", "H\u00f4m nay b\u1ed5n t\u01b0\u1edbng \u0111\u1ebfn \u0111\u00e2y, ng\u1ee1 c\u00f3 th\u1ec3 so ki\u1ebfm v\u1edbi anh h\u00f9ng, n\u00e0o ng\u1edd ch\u1ec9 th\u1ea5y l\u0169 chu\u1ed9t ch\u1ea1y nh\u00e1o nh\u00e0o trong th\u00e0nh t\u00ecm ch\u1ed7 tr\u1ed1n!"}, {"00", "Qu\u00e2n s\u01b0 c\u00f3 bi\u1ebft ng\u01b0\u1eddi d\u01b0\u1edbi kia l\u00e0 ai kh\u00f4ng?"}, {"08", "Nguy\u1ec5n Tr\u00ed Kh\u1ea3, t\u01b0\u1edbng ti\u00ean phong c\u1ee7a Nguy\u1ec5n Si\u00eau, d\u0169ng m\u00e3nh nh\u01b0ng v\u00f4 m\u01b0u. T\u01b0\u1edbng qu\u00e2n, h\u00e3y r\u00e1ng nh\u1eabn nh\u1ecbn."}, {"29", "L\u0169 chu\u1ed9t nghe \u0111\u00e2y! Th\u1eddi gian c\u1ee7a b\u1ed5n t\u01b0\u1edbng qu\u00e2n c\u00f3 h\u1ea1n, trong h\u00f4m nay n\u1ebfu kh\u00f4ng ra kh\u1ecfi hang, ta s\u1ebd san b\u1eb1ng n\u01a1i n\u00e0y."}, {"00", "... ... ..."}, {"29", "Th\u1eadt ngoan c\u1ed1! \u0110\u1ec3 xem l\u0169 chu\u1ed9t c\u00e1c ng\u01b0\u01a1i tr\u1ed1n \u0111\u01b0\u1ee3c bao l\u00e2u?"}, {"00", "\u0110\u1ecbch t\u1ea5n c\u00f4ng, m\u1ecdi ng\u01b0\u1eddi v\u00e0o v\u1ecb tr\u00ed!"}};
        stringArrayArray[21] = new String[][]{{"07", "\u00c2m m\u01b0u ph\u00e1 th\u00e0nh \u0110\u1ed7 \u0110\u1ed9ng th\u1ea5t b\u1ea1i, Nguy\u1ec5n Si\u00eau \u0111\u00e3 \u0111\u1eafp th\u00e0nh cao h\u01a1n \u0111\u1ec3 ph\u00f2ng b\u1ecb. Mu\u1ed1n ti\u1ebfn qu\u00e2n v\u00e0o T\u00e2y Ph\u00f9 Li\u1ec7t e r\u1ea5t kh\u00f3, qu\u00e2n s\u01b0 c\u00f3 cao ki\u1ebfn g\u00ec kh\u00f4ng?"}, {"08", "T\u01b0\u1edbng qu\u00e2n ch\u1edb lo! Nguy\u1ec5n Si\u00eau th\u1eadn tr\u1ecdng ph\u00f2ng b\u1ecb, nh\u01b0 v\u1eady tr\u1eadn chi\u1ebfn v\u1eeba r\u1ed3i binh l\u1ef1c c\u1ee7a h\u1eafn hao t\u1ed5n kh\u00e1 n\u1eb7ng, h\u1eafn s\u1ebd ph\u1ea3i \u0111\u00edch th\u00e2n \u0111i c\u1ea7u c\u1ee9u vi\u1ec7n binh c\u1ee7a 2 ng\u01b0\u1eddi anh Nguy\u1ec5n Th\u1ee7 Ti\u1ec7p ho\u1eb7c Nguy\u1ec5n Khoan."}, {"09", "V\u1eady c\u00f3 ngh\u0129a l\u00e0 T\u00e2y Ph\u00f9 Li\u1ec7t nh\u01b0 r\u1eafn m\u1ea5t \u0111\u1ea7u ?!"}, {"08", "T\u01b0\u1edbng qu\u00e2n n\u00f3i r\u1ea5t ph\u1ea3i! \u0110\u00f3 ch\u00ednh l\u00e0 y\u1ebfu \u0111i\u1ec3m c\u1ee7a T\u00e2y Ph\u00f9 Li\u1ec7t, \u0111\u00eam mai qu\u00e2n ta n\u1ed5i l\u1eeda \u0111\u1ed3ng lo\u1ea1t \u0111\u1ed1t c\u1eeda \u0110\u00f4ng, c\u1eeda T\u00e2y, c\u1eeda Nam th\u00ec ch\u1eafc binh l\u00ednh s\u1ebd ho\u1ea3ng lo\u1ea1n."}, {"07", "\u0110\u01b0\u1ee3c l\u1eafm! Ta s\u1ebd h\u1ecfi t\u1ed9i ch\u00fang nh\u1eefng ng\u00e0y qua."}, {"08", "Tr\u1eadn n\u00e0y, nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i l\u1ea5y \u0111\u01b0\u1ee3c th\u00e0nh. M\u1ecdi ng\u01b0\u1eddi tranh th\u1ee7 ngh\u1ec9 ng\u01a1i, \u0111\u00eam mai xu\u1ea5t binh."}};
        stringArrayArray[22] = new String[][]{{"00", "Tr\u00ed Kh\u1ea3! Ta \u0111\u1ebfn h\u1ecfi t\u1ed9i ng\u01b0\u01a1i \u0111\u00e2y!"}, {"29", "Ch\u1ec9 l\u00e0 con chu\u1ed9t nh\u1eaft, b\u1ed5n t\u01b0\u1edbng s\u1ebd h\u00f3a ki\u1ebfp cho ng\u01b0\u01a1i!"}, {"00", "T\u1ef1 tin th\u00ec c\u1ee9 \u0111\u1ebfn \u0111\u00e2y!!!"}};
        stringArrayArray[23] = new String[][]{{"00", "Nguy\u1ec5n Si\u00eau, ch\u1ea1y \u0111\u00e2u cho tho\u00e1t. N\u1ea1p m\u1ea1ng !!"}, {"28", "Mu\u1ed1n c\u1ea3n ta \u01b0 !? M\u1ed9ng t\u01b0\u1edfng qu\u00e1 \u0111\u1ea5y !"}};
        String[][] stringArrayArray3 = new String[14][];
        stringArrayArray3[0] = new String[]{"09", "Hay tin Nguy\u1ec5n Si\u00eau b\u1ecb di\u1ec7t. Nguy\u1ec5n Khoan v\u00e0 Ki\u1ec1u C\u00f4ng H\u00e3n \u0111\u1eb5 li\u00ean k\u1ebft, c\u00f9ng tr\u1ea5n th\u1ee7 \u1edf v\u00f9ng Tam \u0110\u00e1i. L\u00fd Khu\u00ea v\u00e0 Nguy\u1ec5n Th\u1ee7 Ti\u1ec7p th\u00ec d\u1ef1ng tuy\u1ebfn ph\u00f2ng th\u1ee7 \u1edf Si\u00eau Lo\u1ea1i, xem ra ta g\u1eb7p kh\u00f3 kh\u0103n l\u1edbn r\u1ed3i."};
        stringArrayArray3[1] = new String[]{"08", "T\u01b0\u1edbng qu\u00e2n \u0111\u1eebng qu\u00e1 lo! M\u1ed1i li\u00ean k\u1ebft gi\u1eefa L\u00fd Khu\u00ea v\u00e0 Nguy\u1ec5n Th\u1ee7 Ti\u1ec7p ngo\u00e0i m\u1eb7t nh\u00ecn r\u1ea5t ch\u1eafc ch\u1eafn, nh\u01b0ng th\u1ef1c ch\u1ea5t l\u1ea1i r\u1ea5t y\u1ebfu. Hai ng\u01b0\u1eddi n\u00e0y t\u1eeb l\u00e2u \u0111\u00e3 c\u00f3 m\u1ed1i hi\u1ec1m kh\u00edch v\u1edbi nhau, n\u00ean c\u1eaft \u0111\u1ee9t m\u1ed1i li\u00ean k\u1ebft n\u00e0y kh\u00f4ng ph\u1ea3i l\u00e0 kh\u00f3."};
        stringArrayArray3[2] = new String[]{"07", "Qu\u00e2n s\u01b0 \u0111\u00e3 c\u00f3 cao ki\u1ebfn g\u00ec kh\u00f4ng?"};
        stringArrayArray3[3] = new String[]{"08", "Cao ki\u1ebfn th\u00ec kh\u00f4ng, nh\u01b0ng t\u00f4i c\u00f3 m\u1eb9o n\u00e0y. N\u0103m ng\u00e0y n\u1eefa 49 ng\u00e0y m\u1ea5t c\u1ee7a Nguy\u1ec5n Si\u00eau, ch\u1eafc ch\u1eafn Nguy\u1ec5n Th\u1ee7 Ti\u1ec7p s\u1ebd tr\u1edf v\u1ec1 Ti\u00ean Du. Cho m\u1ed9t nh\u00f3m ng\u01b0\u1eddi tr\u00e0 tr\u1ed9n v\u00e0o th\u00e0nh Si\u00eau Lo\u1ea1i, n\u1eeda \u0111\u00eam \u0111\u1ed1t c\u1ed5ng b\u1eafc. B\u00ean ngo\u00e0i ta gi\u1ea3 l\u00e0m qu\u00e2n c\u1ee7a Th\u1ee7 Ti\u1ec7p tung c\u1edd x\u00ed, n\u1ed5i tr\u1ed1ng tr\u1eadn, \u0111i t\u1eeb h\u01b0\u1edbng Ti\u00ean Du v\u00e0o ph\u00e1 th\u00e0nh. V\u1edbi t\u00ednh \u0111a nghi, L\u00fd Khu\u00ea s\u1ebd t\u01b0\u1edfng Th\u1ee7 Ti\u1ec7p c\u00f2n nu\u00f4i th\u00f9 c\u0169, l\u1ee3i d\u1ee5ng \u0111\u00e2m l\u00e9n sau l\u01b0ng. N\u1ed9i chi\u1ebfn x\u1ea3y ra, vi\u1ec7c l\u1ea5y th\u00e0nh Si\u00eau Lo\u1ea1i d\u1ec5 nh\u01b0 tr\u1edf b\u00e0n tay."};
        stringArrayArray3[4] = new String[]{"07", "L\u01b0u qu\u00e2n s\u01b0, vi\u1ec7c tr\u00e0 tr\u1ed9n h\u00e3y \u0111\u1ec3 t\u00f4i c\u00f9ng c\u00e1c anh em trong doanh tr\u1ea1i."};
        stringArrayArray3[5] = new String[]{"08", "Vi\u1ec7c n\u00e0y r\u1ea5t nguy hi\u1ec3m..."};
        stringArrayArray3[6] = new String[]{"07", "Qu\u00e2n s\u01b0 h\u00e3y y\u00ean t\u00e2m, t\u00f4i c\u00f3 th\u1ec3 lo li\u1ec7u \u0111\u01b0\u1ee3c."};
        stringArrayArray3[7] = new String[]{"08", "T\u01b0\u1edbng qu\u00e2n h\u00e3y c\u1ea7m theo b\u00ed k\u00edp n\u00e0y, n\u1ebfu g\u1eb7p nguy h\u00e3y m\u1edf ra."};
        stringArrayArray3[8] = new String[]{"08", "Gi\u1edd m\u1ecdi ng\u01b0\u1eddi v\u1ec1 ngh\u1ec9. S\u00e1ng mai, ch\u00fang ta s\u1ebd v\u1ec1 T\u1ebf Giang h\u1ed9i ng\u1ed9 v\u1edbi V\u1ea1n Th\u1eafng V\u01b0\u01a1ng. L\u01b0u c\u01a1 c\u00f3 vi\u1ec7c ph\u1ea3i l\u00e0m \u1edf \u0110\u1ed7 \u0110\u1ed9ng, t\u00f4i s\u1ebd \u0111\u1ebfn sau. "};
        String[] stringArray2 = new String[2];
        stringArray2[1] = "Qu\u00e2n s\u01b0, xin c\u00e1o lui.";
        stringArrayArray3[9] = stringArray2;
        stringArrayArray3[10] = new String[]{"08", "{p} t\u01b0\u1edbng qu\u00e2n xin d\u1eebng b\u01b0\u1edbc, t\u00f4i c\u00f3 chuy\u1ec7n c\u1ea7n b\u00e0n v\u1edbi t\u01b0\u1edbng qu\u00e2n!"};
        stringArrayArray3[11] = new String[]{"00", "Xin qu\u00e2n s\u01b0 c\u1ee9 n\u00f3i!"};
        stringArrayArray3[12] = new String[]{"08", "T\u00f4i nghe n\u00f3i, \u1edf v\u00f9ng \u0110\u1ed7 \u0110\u1ed9ng c\u00f3 \u0111\u00e1m ng\u01b0\u1eddi t\u1ef1 x\u01b0ng l\u00e0 con ch\u00e1u Ng\u00f4 ti\u00ean ch\u00faa \u0111\u00e3 kh\u1edfi binh ti\u1ebfn \u0111\u00e1nh Hoa L\u01b0, nh\u01b0ng khi \u0111\u1ebfn \u00d4 Man th\u00ec \u0111\u1ee5ng \u0111\u1ed9 v\u1edbi h\u00e0o tr\u01b0\u1edfng l\u00e0ng \u1ea5y l\u00e0 Ng\u00f4 Ph\u00f3. \u0110\u00e1m ng\u01b0\u1eddi n\u00e0y kh\u00f4ng di\u1ec7t sau n\u00e0y s\u1ebd r\u1eafc r\u1ed1i, t\u01b0\u1edbng qu\u00e2n h\u00e3y c\u00f9ng t\u00f4i \u0111\u1ebfn gi\u00fap Ng\u00f4 Ph\u00f3 m\u1ed9t tay. Ng\u00e0i h\u00e3y v\u1ec1 chu\u1ea9n b\u1ecb, s\u1edbm mai ta s\u1ebd l\u00ean \u0111\u01b0\u1eddng. "};
        stringArrayArray3[13] = new String[]{"00", "M\u1ea1t t\u01b0\u1edbng xin c\u00e1o lui!"};
