        String[][] stringArrayArray4 = new String[5][];
        stringArrayArray4[0] = new String[]{"08", "Th\u01b0a \u0110\u1ea1i v\u01b0\u01a1ng, vi\u1ec7c \u1edf T\u00e2y Ph\u00f9 Li\u1ec7t t\u00f4i \u0111\u00e3 s\u1eafp x\u1ebfp xong."};
        stringArrayArray4[1] = new String[]{"06", "Qu\u00e2n s\u01b0, Nguy\u1ec5n Th\u1ee7 Ti\u1ec7p \u0111\u00e3 v\u1ec1 Ti\u00ean Du. Khi n\u00e0o ta s\u1ebd \u0111\u00e1nh v\u00e0o Si\u00eau Lo\u1ea1i?"};
        stringArrayArray4[2] = new String[]{"08", "Theo thu\u1ed9c h\u1ea1 t\u00ednh th\u00ec \u0111\u00eam mai c\u00f3 gi\u00f3 l\u1edbn, n\u1ed9i gi\u00e1n c\u1ee7a ta s\u1ebd \u0111\u1ed1t doanh tr\u1ea1i \u0111\u1ecbch, khi \u0111\u00f3 l\u1eeda lan r\u1ea5t nhanh. Th\u1ea5y l\u1eeda, \u0111\u1ecbch s\u1ebd n\u00e1o lo\u1ea1n, l\u00fac \u0111\u00f3 ta xu\u1ea5t binh \u0111\u00e1nh v\u00e0o Si\u00eau Lo\u1ea1i"};
        stringArrayArray4[3] = new String[]{"06", "\u0110\u01b0\u1ee3c, \u0111\u00eam mai ta s\u1ebd l\u1ea5y Si\u00eau Lo\u1ea1i. M\u1ecdi ng\u01b0\u1eddi h\u00e3y v\u1ec1 chu\u1ea9n b\u1ecb."};
