        stringArrayArray[28] = new String[][]{{"00", "L\u00fd Khu\u00ea \u1edf \u0111\u1eb1ng kia! Mau \u0111u\u1ed5i theo."}, {"30", "Mau! Mau ch\u1ea1y v\u00e0o l\u00e0ng."}, {"00", "Ch\u1ea1y \u0111\u00e2u cho tho\u00e1t!"}};
        String[][] stringArrayArray5 = new String[3][];
        stringArrayArray5[0] = new String[]{"08", "Th\u1ea5t b\u1ea1i \u1edf Si\u00eau Lo\u1ea1i, binh l\u1ef1c c\u1ee7a Nguy\u1ec5n Th\u1ee7 Ti\u1ec7p \u0111\u00e3 m\u1ea5t h\u01a1n n\u1eefa, qu\u00e2n l\u00ednh g\u1ea7n nh\u01b0 m\u1ea5t h\u1ebft nhu\u1ec7 kh\u00ed. \u0110\u00e2y l\u00e0 th\u1eddi c\u01a1 thu\u1eadn l\u1ee3i cho ta \u0111\u00e1nh Ti\u00ean Du. \u0110\u1ea1i v\u01b0\u01a1ng, h\u00e3y cho xu\u1ea5t binh."};
        stringArrayArray5[1] = new String[]{"06", "Nguy\u1ec5n B\u1eb7c, \u00f4ng d\u1eabn qu\u00e2n \u0111\u00e1nh v\u00e0o c\u00e1nh tr\u00e1i Ti\u00ean Du. L\u00ea Ho\u00e0n th\u00ec \u0111\u00e1nh v\u00e0o c\u00e1nh ph\u1ea3i. Ta c\u00f9ng c\u00e1c t\u01b0\u1edbng kh\u00e1c t\u1ea5n c\u00f4ng tr\u1ef1c di\u1ec7n. M\u1ecdi ng\u01b0\u1eddi, ti\u1ebfn th\u1eb3ng Ti\u00ean Du!"};
