        String[][] stringArrayArray6 = new String[5][];
        stringArrayArray6[0] = new String[]{"07", "H\u1eeb, kh\u00f4ng ng\u1edd t\u00ean ph\u1ea3n t\u1eb7c L\u00e3 X\u1eed B\u00ecnh g\u1eedi th\u01b0 c\u1ea7u c\u1ee9u li\u00ean qu\u00e2n Nguy\u1ec5n Khoan v\u00e0 Ki\u1ec1u C\u00f4ng H\u00e3n, 7 ng\u00e0y n\u1eefa li\u00ean qu\u00e2n s\u1ebd \u0111\u1ebfn C\u1ed5 Loa."};
        stringArrayArray6[1] = new String[]{"06", "N\u1ebfu li\u00ean qu\u00e2n h\u1ee3p s\u1ee9c v\u1edbi L\u1eef X\u1eed B\u00ecnh, ta s\u1ebd kh\u00f3 ti\u1ebfn v\u00e0o C\u1ed5 Loa. Qu\u00e2n s\u01b0, \u00f4ng c\u00f3 k\u1ebf s\u00e1ch g\u00ec kh\u00f4ng?"};
        stringArrayArray6[2] = new String[]{"08", "Hi\u1ec7n t\u1ea1i qu\u00e2n l\u1ef1c \u1edf C\u1ed5 Loa c\u00f2n y\u1ebfu. Trong 5 ng\u00e0y, ph\u1ea3i \u0111\u00e1nh v\u00e0o C\u1ed5 Loa tr\u01b0\u1edbc khi li\u00ean qu\u00e2n \u0111\u1ebfn. N\u1ebfu kh\u00f4ng qu\u00e2n ta kh\u00f4ng c\u00f2n c\u01a1 h\u1ed9i n\u00e0o kh\u00e1c."};
