        stringArrayArray[33] = new String[][]{{"35", "Ch\u1ee7 c\u00f4ng, qu\u00e2n ta \u0111\u00e3 th\u1ea5t th\u1ee7..."}, {"34", "Grrr....Mau, r\u00fat v\u1ec1 Tam \u0110\u00e1i."}, {"00", "L\u1eef X\u1eed B\u00ecnh, ng\u01b0\u01a1i h\u1ebft \u0111\u01b0\u1eddng r\u1ed3i! S\u00e1aatttt"}};
        String[][] stringArrayArray7 = new String[6][];
        stringArrayArray7[0] = new String[]{"06", "Bi\u1ebft qu\u00e2n ta \u0111\u00e3 chi\u1ebfm C\u1ed5 Loa, li\u00ean qu\u00e2n r\u00fat v\u1ec1 c\u1ed1 th\u1ee7 \u1edf Tam \u0110\u00e1i. B\u00e2y gi\u1edd \u0111\u00e1nh t\u1eeb C\u1ed5 Loa v\u00e0o Tam \u0110\u00e1i r\u1ea5t kh\u00f3, m\u1ecdi ng\u01b0\u1eddi c\u00f3 k\u1ebf s\u00e1ch g\u00ec kh\u00f4ng? "};
        stringArrayArray7[1] = new String[]{"08", "N\u1ebfu Tam \u0110\u00e1i \u0111\u00e1nh kh\u00f3 th\u00ec ta s\u1ebd \u0111\u00e1nh Phong Ch\u00e2u tr\u01b0\u1edbc."};
        stringArrayArray7[2] = new String[]{"06", "Phong Ch\u00e2u?"};
        stringArrayArray7[3] = new String[]{"08", "Ki\u1ec1u C\u00f4ng H\u00e3n \u0111em qu\u00e2n xu\u1ed1ng Tam \u0110\u00e1i, ch\u1eafc ch\u1eafn Phong Ch\u00e2u s\u1ebd s\u01a1 h\u1edf. Ta cho 2 \u0111\u1ea1o qu\u00e2n ti\u1ebfn t\u1eeb 2 h\u01b0\u1edbng \u0110\u01b0\u1eddng L\u00e2m v\u00e0 C\u1ed5 Loa \u0111\u00e1nh v\u00e0o Tam \u0110\u00e1i. M\u1eb7t kh\u00e1c cho \u0111\u1ea1o qu\u00e2n kh\u00e1c \u0111i v\u00f2ng \u0111\u01b0\u1eddng n\u00fai \u0111\u00e1nh Phong Ch\u00e2u, Ki\u1ec1u C\u00f4ng H\u00e3n ch\u1eafc ch\u1eafn r\u00fat qu\u00e2n v\u1ec1. L\u00fac \u0111\u00f3 ch\u1ec9 c\u00f2n m\u00ecnh Nguy\u1ec5n Khoan \u1edf Tam \u0110\u00e1i, ta s\u1ebd \u0111\u00e1nh v\u00e0o \u0111\u01b0\u1ee3c."};
        stringArrayArray7[4] = new String[]{"06", "Nguy\u1ec5n B\u1eb7c, {p} t\u01b0\u1edbng qu\u00e2n h\u00e3y \u0111em qu\u00e2n \u0111\u1ebfn \u0110\u01b0\u1eddng L\u00e2m, L\u00ea Ho\u00e0n d\u1eabn qu\u00e2n \u0111\u1ebfn Phong Ch\u00e2u, c\u00e1c t\u01b0\u1edbng c\u00f2n l\u1ea1i h\u00e3y theo ta \u0111\u00e1nh th\u1eb3ng t\u1eeb C\u1ed5 Loa \u0111\u1ebfn. M\u1ecdi ng\u01b0\u1eddi v\u1ec1 ngh\u1ec9 ng\u01a1i, s\u1edbm mai ta s\u1ebd xu\u1ea5t qu\u00e2n!"};
