        stringArrayArray7[5] = stringArray6;
        stringArrayArray[34] = stringArrayArray7;
        stringArrayArray[36] = new String[][]{{"39", "B\u00e1oooo!! Th\u01b0a ch\u1ee7 c\u00f4ng, Phong Ch\u00e2u b\u1ecb t\u1ea5n c\u00f4ng!"}, {"38", "Mau! V\u1ec1 h\u1ed7 tr\u1ee3 Phong Ch\u00e2u."}, {"39", "B\u00e1oooo!! T\u01b0\u1edbng gi\u1eb7c L\u00ea Ho\u00e0n \u0111\u00e3 chi\u1ebfm Phong Ch\u00e2u!"}, {"38", "Grr..grr...Ta \u0111\u00e3 qu\u00e1 s\u01a1 \u00fd! Lui v\u1ec1 H\u1ed3i H\u1ed3 t\u1ea1m l\u00e1nh m\u1ed9t th\u1eddi gian."}, {"38", "\u0110inh B\u1ed9 L\u0129nh! Ta th\u1ec1 s\u1ebd l\u1ea5y l\u1ea1i Phong Ch\u00e2u."}, {"00", "Nguy\u1ec5n Khoan, c\u00f3 gan ra \u0111\u00e2y so cao th\u1ea5p v\u1edbi ta!"}, {"36", "Ng\u00f4ng cu\u1ed3ng! H\u00f4m nay ta s\u1ebd l\u1ea5y \u0111\u1ea7u b\u1ecdn bay \u0111\u1ec3 tr\u1ea3 th\u00f9 c\u1ee7a Nguy\u1ec5n Si\u00eau v\u00e0 Th\u1ee7 Ti\u1ec7p."}};
        stringArrayArray[37] = new String[][]{{"08", "\u0110\u1ea1i v\u01b0\u01a1ng, h\u1ea1 t\u01b0\u1edbng c\u0169 c\u1ee7a Tr\u1ea7n l\u00e3o c\u00f4ng \u0111\u00e3 l\u00e0m ph\u1ea3n, h\u1eafn \u0111em qu\u00e2n \u0111\u00e1nh v\u00e0o K\u1ef3 B\u1ed1. M\u1ecdi ng\u01b0\u1eddi trong th\u00e0nh \u0111ang c\u1ed1 th\u1ee7, l\u01b0\u01a1ng th\u1ef1c ch\u1ec9 \u0111\u1ee7 d\u00f9ng trong v\u00e0i ng\u00e0y, ta ph\u1ea3i \u0111em qu\u00e2n \u0111\u1ebfn gi\u1ea3i v\u00e2y ngay!"}, {"06", "{p} t\u01b0\u1edbng qu\u00e2n, khanh h\u00e3y \u0111em qu\u00e2n tr\u1edf v\u1ec1 \u1ee9ng c\u1ee9u K\u1ef3 B\u1ed1. Nh\u01b0ng ng\u01b0\u1eddi c\u00f2n l\u1ea1i theo ta \u0111\u00e1nh v\u00e0o Phong Ch\u00e2u."}, {"00", "Tu\u00e2n l\u1ec7nh \u0110\u1ea1i v\u01b0\u01a1ng!"}};
        stringArrayArray[38] = new String[][]{{"00", "Ph\u1ea3n t\u1eb7c, c\u00f3 ta \u0111\u1ebfn \u0111\u00e2y, h\u00e3y mau ch\u1ecbu t\u1ed9i!"}, {"33", "S\u1ee9c ng\u01b0\u01a1i c\u00f2n k\u00e9m l\u1eafm, ch\u01b0a \u0111\u1ee7 \u0111\u00e2u!"}, {"00", "Ch\u1edb ng\u00f4ng cu\u1ed3ng! H\u00e3y xem \u0111\u00e2y !!!"}};
        stringArrayArray[39] = new String[][]{{"06", "Th\u1ea5t b\u1ea1i \u1edf Phong Ch\u00e2u v\u00e0 Tam \u0110\u00e1i, Ki\u1ec1u C\u00f4ng H\u00e3n \u0111\u00e3 r\u00fat qu\u00e2n th\u1eb3ng v\u1ec1 H\u1ed3i H\u1ed3 n\u01b0\u01a1ng nh\u1edd em h\u1eafn l\u00e0 Ki\u1ec1u Thu\u1eadn. \u0110\u1ecba h\u00ecnh \u1edf \u0111\u00f3 hi\u1ec3m tr\u1edf, r\u1ea5t kh\u00f3 t\u1ea5n c\u00f4ng, qu\u00e2n s\u01b0 c\u00f3 k\u1ebf s\u00e1ch g\u00ec kh\u00f4ng?"}, {"08", "Th\u01b0a \u0110\u1ea1i V\u01b0\u01a1ng, th\u1ef1c ra \u0111\u1ecba h\u00ecnh hi\u1ec3m tr\u1edf ch\u00ednh l\u00e0 y\u1ebfu \u0111i\u1ec3m c\u1ee7a H\u1ed3i H\u1ed3!"}, {"06", "Y\u1ebfu \u0111i\u1ec3m!? Ta ch\u01b0a hi\u1ec3u, qu\u00e2n s\u01b0 h\u00e3y n\u00f3i r\u00f5."}, {"08", "Th\u00e0nh H\u1ed3i H\u1ed3 xung quanh l\u00e0 v\u00f9ng \u0111\u1ed3i n\u00fai hi\u1ec3m tr\u1edf, ta kh\u00f4ng n\u00ean t\u1ea5n c\u00f4ng, chia qu\u00e2n ra \u0111\u00f3ng \u1edf  n\u01a1i hi\u1ec3m y\u1ebfu ng\u0103n ch\u1eb7n ngu\u1ed3n n\u01b0\u1edbc. V\u00e2y ph\u1ee5c ba ng\u00e0y, t\u1ef1 ch\u00fang s\u1ebd m\u00f2 ra, l\u00fac \u1ea5y ta s\u1ebd di\u1ec7t \u0111\u01b0\u1ee3c."}, {"06", "Qu\u00e2n s\u01b0 n\u00f3i ph\u1ea3i l\u1eafm, 12 s\u1ee9 qu\u00e2n nay ch\u1ec9 c\u00f2n anh em h\u1ecd Ki\u1ec1u, ta c\u0169ng kh\u00f4ng c\u1ea7n ph\u1ea3i v\u1ed9i. Ch\u00fang ta h\u00e3y theo k\u1ebf c\u1ee7a qu\u00e2n s\u01b0."}, {"00", "Tu\u00e2n l\u1ec7nh \u0111\u1ea1i v\u01b0\u01a1ng!"}};
        stringArrayArray[41] = new String[][]{{"40", "Huynh tr\u01b0\u1edfng, l\u01b0\u01a1ng th\u1ef1c trong th\u00e0nh ch\u1eb3ng c\u00f2n bao nhi\u00eau. N\u1ebfu ti\u1ebfp t\u1ee5c \u1edf trong th\u00e0nh e r\u1eb1ng s\u1ebd kh\u00f4ng qua kh\u1ecfi."}, {"38", "V\u1edbi t\u00ecnh th\u1ebf n\u00e0y, n\u00ean t\u00ecm c\u00e1ch tho\u00e1t th\u00e2n tr\u01b0\u1edbc."}, {"40", "\u0110\u1ecbch \u0111\u00e3 bao v\u00e2y 4 h\u01b0\u1edbng, ta ch\u1ea1y \u0111i \u0111\u00e2u b\u00e2y gi\u1edd."}, {"38", "\u1ede c\u1eeda B\u1eafc, l\u1ef1c l\u01b0\u1ee3ng c\u1ee7a \u0111\u1ecbch y\u1ebfu nh\u1ea5t. N\u1ebfu ph\u00e1 \u0111\u01b0\u1ee3c v\u00f2ng v\u00e2y, th\u00ec ch\u1ea1y l\u00ean ph\u01b0\u01a1ng B\u1eafc xin nh\u00e0 T\u1ed1ng c\u1ee9u vi\u1ec7n."}, {"40", "\u0110\u1ec7 s\u1ebd ch\u1ecdn ra 1 \u0111\u00e1m qu\u00e2n tinh nhu\u1ec7, \u0111\u00eam nay ch\u00fang ta ph\u00e1 v\u00f2ng v\u00e2y."}, {"00", "Ki\u1ec1u t\u1eb7c, ch\u1ea1y \u0111\u00e2u cho tho\u00e1t!"}};
        String[][] stringArrayArray8 = new String[5][];
