        stringArrayArray12[2] = new String[][]{{"12", "M\u00f4 ph\u1eadt! B\u1ea7n t\u0103ng ti\u1ebfp \u0111\u00f3n ch\u1eadm tr\u1ec5, L\u01b0u ti\u00ean sinh h\u00e3y l\u01b0\u1ee3ng th\u1ee9."}, {"08", "\u0110\u1ea1i s\u01b0 \u0111\u1eebng kh\u00e1ch s\u00e1o! H\u00f4m nay t\u00f4i \u0111\u1ebfn \u0111\u00e2y c\u00f3 vi\u1ec7c c\u1ea7n ng\u00e0i gi\u00fap \u0111\u1ee1. "}, {"12", "L\u01b0u qu\u00e2n s\u01b0, n\u1ebfu gi\u00fap \u0111\u01b0\u1ee3c b\u1ea7n t\u0103ng s\u1ebd c\u1ed1 h\u1ebft s\u1ee9c."}, {"08", "Kh\u00f4ng d\u1ea5u g\u00ec \u0111\u1ea1i s\u01b0, binh l\u1ef1c c\u1ee7a V\u1ea1n Th\u1eafng V\u01b0\u01a1ng tuy uy d\u0169ng nh\u01b0ng v\u1eabn c\u00f2n thi\u1ebfu ng\u01b0\u1eddi ch\u1ec9 d\u1eabn. \u0110\u1ea1i s\u01b0, xin h\u00e3y gi\u00fap m\u1ed9t tay."}, {"12", "Vi\u1ec7c n\u00e0y h\u01a1i kh\u00f3 cho b\u1ea7n t\u0103ng v\u00ec ch\u00f9a c\u00f3 quy \u0111\u1ecbnh n\u1ebfu th\u1ec9nh s\u01b0 xu\u1ed1ng n\u00fai ph\u1ea3i ph\u00e1 \u0111\u01b0\u1ee3c La H\u00e1n Tr\u1eadn. Tr\u01b0\u1edbc nay ch\u01b0a c\u00f3 ai ph\u00e1 \u0111\u01b0\u1ee3c tr\u1eadn n\u00e0y, L\u01b0u ti\u00ean sinh e r\u1eb1ng t\u00f4i kh\u00f3 m\u00e0 gi\u00fap \u00f4ng."}, {"08", "........"}, {"00", "L\u01b0u ti\u00ean sinh, h\u00e3y \u0111\u1ec3 ti\u1ec3u t\u01b0\u1edbng th\u1eed ph\u00e1 La H\u00e1n Tr\u1eadn"}, {"08", "T\u01b0\u1edbng qu\u00e2n, h\u00e3y tr\u1eadn tr\u1ecdng."}};
        stringArrayArray12[3] = new String[][]{{"14", "C\u00e1c ng\u01b0\u01a1i l\u00e0 ai, h\u00e3y mau tr\u00e1nh \u0111\u01b0\u1eddng cho ta."}, {"00", "L\u00e1o x\u01b0\u1ee3c, ti\u1ebfp chi\u00eau!"}};
        stringArrayArray12[4] = new String[][]{{"13", "Ch\u1eb3ng hay t\u01b0\u1edbng qu\u00e2n gh\u00e9 \u0111\u1ebfn t\u1ec7 x\u00e1 c\u00f3 vi\u1ec7c c\u1ea7n g\u00ec ch\u1ec9 b\u1ea3o?"}, {"00", "Ta \u0111i l\u1ea1c \u0111\u1ebfn \u0111\u00e2y, xin h\u1ecfi cao danh qu\u00fd t\u00e1nh c\u1ee7a ti\u00ean sinh."}, {"13", "T\u1ea1i h\u1ea1 h\u1ecd B\u00f9i t\u00ean Quang D\u0169ng..."}, {"00", "Ng\u01b0\u1eddi l\u00e0 B\u00f9i Quang D\u0169ng !? Nghe danh \u0111\u00e3 l\u00e2u, h\u00f4m nay c\u00f3 c\u01a1 h\u1ed9i g\u1eb7p g\u1ee1, xin ti\u00ean sinh ch\u1ec9 gi\u00e1o."}, {"13", "Th\u1eadt kh\u00f4ng d\u00e1m. T\u01b0\u1edbng qu\u00e2n! xin m\u1eddi."}};
        stringArrayArray12[5] = new String[][]{{"19", "T\u01b0\u1edbng qu\u00e2n, xin h\u00e3y d\u1eebng b\u01b0\u1edbc."}, {"00", "C\u00f4ng t\u1eed l\u00e0...."}, {"19", "C\u1ef1 L\u1ea1ng l\u00e0 ch\u00e1u n\u1ed9i c\u1ee7a Ph\u1ea1m L\u1ec7nh C\u00f4ng \u2013 \u0110\u00f4ng gi\u00e1p t\u01b0\u1edbng qu\u00e2n d\u01b0\u1edbi th\u1eddi Ng\u00f4 ti\u00ean ch\u00faa, ch\u1eb3ng may chi\u1ebfn tranh lo\u1ea1n l\u1ea1c n\u00ean lui v\u1ec1 \u0111\u00e2y ch\u1edd minh ch\u1ee7. Hay tin qu\u00e2n c\u1ee7a V\u1ea1n Th\u1eafng V\u01b0\u01a1ng \u0111i qua, ch\u00fang t\u00f4i d\u1eabn m\u1ecdi ng\u01b0\u1eddi \u0111\u1ebfn gi\u00fap m\u1ed9t tay."}, {"00", "V\u1ea1n Th\u1eafng V\u01b0\u01a1ng \u0111ang \u1edf ngo\u00e0i chi\u1ebfn tr\u01b0\u1eddng, c\u00f4ng t\u1eed h\u00e3y theo t\u00f4i."}};
        stringArrayArray12[6] = new String[][]{{"06", "Ch\u00e2n L\u01b0u \u0111\u1ec7! Giang s\u01a1n \u0111\u1ea1i lo\u1ea1n r\u1ea5t c\u1ea7n ng\u01b0\u1eddi t\u00e0i, \u0111\u1ec7 h\u00e3y xu\u1ed1ng n\u00fai gi\u00fap ta m\u1ed9t phen."}, {"11", "B\u1ed9 L\u0129nh huynh, \u0111\u00e1m y\u00eau qu\u00e1i \u1edf Tam \u0110\u1ea3o \u0111ang l\u1ed9ng h\u00e0nh. N\u1ebfu \u0111\u1ec7 theo huynh xu\u1ed1ng n\u00fai e ch\u00f9a s\u1ebd kh\u00f3 m\u00e0 gi\u1eef \u0111\u01b0\u1ee3c."}, {"06", "\u0110\u1ec7 y\u00ean t\u00e2m, ta s\u1ebd gi\u00fap \u0111\u1ec7 di\u1ec7t \u0111\u00e1m y\u00eau \u0111\u00f3."}};
        e = stringArrayArray12;
        String[][][] stringArrayArray14 = new String[8][][];
        stringArrayArray14[0] = new String[][]{{"06", "Y\u00eau qu\u00e1i \u0111\u00e3 b\u1ecb di\u1ec7t, m\u1ecdi ng\u01b0\u1eddi an to\u00e0n r\u1ed3i!"}, {"16", "\u0110a t\u1ea1 \u0111\u1ea1i v\u01b0\u01a1ng c\u1ee9u gi\u00fap!"}, {"06", "Ti\u1ec3u th\u01b0, h\u00e3y \u0111\u1ee9ng l\u00ean. M\u1ecdi ng\u01b0\u1eddi trong s\u01a1n trang \u0111\u00e2u c\u1ea3, sao ch\u1ec9 c\u00f2n l\u1ea1i m\u00ecnh n\u00e0ng?"}, {"16", "M\u1ecdi ng\u01b0\u1eddi \u0111\u00e3 b\u1ecb y\u00eau qu\u00e1i s\u00e1t h\u1ea1i, V\u00e2n Nga may m\u1eafn \u0111\u01b0\u1ee3c \u0111\u1ea1i v\u01b0\u01a1ng k\u1ecbp th\u1eddi c\u1ee9u gi\u00fap. N\u1ebfu kh\u00f4ng ch\u00ea, xin \u0111\u1ea1i v\u01b0\u01a1ng h\u00e3y cho ti\u1ec3u n\u1eef theo h\u1ea7u \u0111\u1ec3 b\u00e1o \u0111\u00e1p \u00e2n t\u00ecnh."}, {"06", "\u1ede \u0111\u00e2y hoang v\u1eafng nguy hi\u1ec3m, m\u1ed9t m\u00ecnh n\u00e0ng \u1edf l\u1ea1i c\u0169ng kh\u00f4ng t\u1ed1t. H\u00e3y theo c\u1eadn v\u1ec7 c\u1ee7a ta v\u1ec1 Hoa L\u01b0 tr\u01b0\u1edbc, ta v\u1ec1 g\u1eb7p n\u00e0ng sau."}, {"16", "T\u1ea1 \u01a1n \u0111\u1ea1i v\u01b0\u01a1ng"}};
        stringArrayArray14[1] = new String[][]{{"06", "Kh\u00e1 l\u1eafm!"}, {"08", "\u0110\u1ea1i v\u01b0\u01a1ng! qu\u00e2n ta r\u1ea5t c\u1ea7n m\u1ed9t ti\u00ean phong d\u0169ng m\u00e3nh nh\u01b0 v\u1ecb tr\u00e1ng s\u0129 n\u00e0y."}, {"06", "L\u00ea Ho\u00e0n! ta giao ng\u01b0\u01a1i tr\u1ecdng tr\u00e1ch ti\u00ean phong t\u01b0\u1edbng qu\u00e2n."}, {"09", "\u0110a t\u1ea1 \u0111\u1ea1i v\u01b0\u01a1ng. D\u00f9 c\u00f3 th\u1ecbt n\u00e1t x\u01b0\u01a1ng tan, ti\u1ec3u t\u01b0\u1edbng c\u0169ng s\u1ebd ho\u00e0n th\u00e0nh nhi\u1ec7m v\u1ee5 \u0111\u1ea1i v\u01b0\u01a1ng \u0111\u00e3 giao."}};
        stringArrayArray14[2] = new String[][]{{"12", "V\u00f5 c\u00f4ng c\u1ee7a t\u01b0\u1edbng qu\u00e2n th\u1eadt cao th\u00e2m! B\u1ea7n t\u0103ng \u0111\u01b0\u1ee3c m\u1edf r\u1ed9ng t\u1ea7m m\u1eaft."}, {"00", "\u0110\u1ea1i s\u01b0 \u0111\u00e3 qu\u00e1 khen, t\u00f4i ch\u1ec9 may m\u1eafn ph\u00e1 \u0111\u01b0\u1ee3c tr\u1eadn."}, {"12", "L\u01b0u ti\u00ean sinh, h\u00e3y \u0111\u1ee3i t\u00f4i thu x\u1ebfp r\u1ed3i c\u00f9ng \u0111\u1ebfn Hoa L\u01b0."}, {"08", "\u0110\u1ea1i s\u01b0 c\u1ee9 t\u1eeb t\u1eeb thu x\u1ebfp, t\u00f4i s\u1ebd ch\u1edd."}};
        stringArrayArray14[3] = new String[][]{{"08", "T\u01b0\u1edbng qu\u00e2n, h\u00e3y d\u1eebng tay!"}, {"08", "Xin h\u1ecfi tr\u00e1ng s\u0129 c\u00f3 ph\u1ea3i l\u00e0 h\u00e0o tr\u01b0\u1edfng Nguy\u1ec5n Ninh?"}, {"14", "C\u00e1c h\u1ea1 l\u00e0 ai sao l\u1ea1i bi\u1ebft t\u00ean ta?"}, {"08", "Ch\u00fang t\u00f4i l\u00e0 ng\u01b0\u1eddi c\u1ee7a V\u1ea1n Th\u1eafng V\u01b0\u01a1ng, b\u1ea5y l\u00e2u nghe danh h\u00e0o tr\u01b0\u1edfng anh d\u0169ng h\u01a1n ng\u01b0\u1eddi, nay ch\u00fang t\u00f4i \u0111i ngang qua \u0111\u00e2y, n\u1ebfu c\u00f3 m\u1ea1o ph\u1ea1m xin th\u1ee9 l\u1ed7i."}, {"14", "V\u1ea1n Th\u1eafng V\u01b0\u01a1ng !!! Th\u1eadt may qu\u00e1, t\u00f4i c\u0169ng \u0111ang \u0111\u1ebfn Hoa L\u01b0 \u0111\u1ec3 \u0111\u1ea7u qu\u00e2n."}, {"08", "N\u1ebfu Hoa L\u01b0 c\u00f3 th\u00eam v\u1ecb t\u01b0\u1edbng anh d\u0169ng nh\u01b0 h\u00e0o tr\u01b0\u1edfng th\u1eadt l\u00e0 ph\u01b0\u1edbc c\u1ee7a mu\u00f4n d\u00e2n."}, {"14", "M\u1ed9t ch\u00fat t\u00e0i m\u1ecdn, ti\u00ean sinh \u0111\u00e3 qu\u00e1 l\u1eddi. Xin ti\u00ean sinh h\u00e3y \u0111\u01b0a t\u00f4i \u0111i g\u1eb7p V\u1ea1n Th\u1eafng V\u01b0\u01a1ng."}, {"08", "H\u00e0o tr\u01b0\u1edfng, xin m\u1eddi."}};
        stringArrayArray14[4] = new String[][]{{"00", "Ki\u1ebfm ph\u00e1p c\u1ee7a ti\u00ean sinh r\u1ea5t cao th\u00e2m, n\u1ebfu \u1edf l\u1ea1i n\u01a1i n\u00e0y th\u1eadt u\u1ed5ng ph\u00ed. N\u1ebfu kh\u00f4ng ch\u00ea, t\u00f4i s\u1ebd ti\u1ebfn c\u1eed ti\u00ean sinh v\u1edbi V\u1ea1n Th\u1eafng V\u01b0\u01a1ng."}, {"13", "\u0110a t\u1ea1 t\u01b0\u1edbng qu\u00e2n! \u0110\u01b0\u1ee3c g\u00f3p ch\u00fat t\u00e0i m\u1ecdn cho V\u1ea1n Th\u1eafng V\u01b0\u01a1ng th\u1eadt l\u00e0 vinh h\u1ea1nh cho t\u00f4i."}, {"00", "Ti\u00ean sinh, l\u00e0m sao ch\u00fang ta ra kh\u1ecfi v\u00f9ng n\u00e0y?"}, {"13", "T\u01b0\u1edbng qu\u00e2n! h\u00e3y theo t\u00f4i."}};
        stringArrayArray14[7] = new String[][]{{"06", "Y\u00eau qu\u00e1i \u0111\u00e3 di\u1ec7t xong, m\u1ecdi ng\u01b0\u1eddi h\u00e3y mau tr\u1edf v\u1ec1 ch\u00f9a."}, {"11", "\u0110a t\u1ea1 B\u1ed9 L\u0129nh huynh \u0111\u00e3 gi\u00fap \u0111\u1ee1. H\u00e3y \u0111\u1ee3i t\u00f4i thu x\u1ebfp h\u00e0nh l\u00fd xu\u1ed1ng n\u00fai."}};
